# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make_student(last, first):
    return Student("id", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [
            make_student("Halloway", "Juno"),
            make_student("Zane", "Ola"),
            make_student("Dunmere", "Piet")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Zane, Ola"]
        )

    def test_bad_seat_count(self):
        people = [make_student("Zane", "Ola")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
